import express from 'express';
import cors from 'cors';
import { config, validateConfig } from './config/config.js';
import screenshotRoutes from './routes/screenshot.routes.js';
import { errorHandler, notFoundHandler } from './middleware/errorHandler.js';

// Validate environment variables
try {
  validateConfig();
} catch (error) {
  console.error('Configuration Error:', error.message);
  process.exit(1);
}

// Initialize Express app
const app = express();

// Parse JSON and URL-encoded bodies FIRST
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// CORS configuration
const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (mobile apps, Postman, etc.)
    if (!origin) return callback(null, true);

    if (config.cors.allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200
};

// Apply CORS
app.use(cors(corsOptions));

// Request logging in development
if (config.server.nodeEnv === 'development') {
  app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
    next();
  });
}

// Routes
app.use('/api', screenshotRoutes);

// Root endpoint
app.get('/', (req, res) => {
  res.json({
    name: 'Snapshotbanner API',
    version: '1.0.0',
    description: 'Secure middleware for Screenshotlayer API',
    endpoints: {
      health: 'GET /api/health',
      screenshot: 'POST /api/screenshot',
      screenshotProxy: 'POST /api/screenshot/proxy',
      screenshotUrl: 'GET /api/screenshot/url'
    }
  });
});

// Error handling
app.use(notFoundHandler);
app.use(errorHandler);

// Start server
const PORT = config.server.port;
app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════╗
║   Snapshotbanner API Server Running     ║
╠══════════════════════════════════════════╣
║  Environment: ${config.server.nodeEnv.padEnd(27)}║
║  Port:        ${PORT.toString().padEnd(27)}║
║  URL:         http://localhost:${PORT}      ║
╠══════════════════════════════════════════╣
║  Endpoints:                              ║
║  - GET  /                                ║
║  - GET  /api/health                      ║
║  - POST /api/screenshot                  ║
║  - POST /api/screenshot/proxy            ║
║  - GET  /api/screenshot/url              ║
╚══════════════════════════════════════════╝
  `);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

import { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import CanvasEditor from './components/CanvasEditor';
import ControlsPanel from './components/ControlsPanel';

function App() {
  const [urlInput, setUrlInput] = useState('https://example.com');
  const [theme, setTheme] = useState(() => {
    // Check localStorage or system preference
    const saved = localStorage.getItem('theme');
    if (saved) return saved;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [state, setState] = useState({
    width: 1280,
    height: 720,
    bg: '#0b0f1a',
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    retina: true,
    format: 'webp',
    quality: 0.95,
    img: null
  });

  // Save theme preference
  useEffect(() => {
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  const loadImage = (url) => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = url;
    });
  };

  const handleCapture = async () => {
    const url = urlInput.trim() || 'https://example.com';

    try {
      // Call the backend proxy endpoint with POST
      const response = await fetch('http://localhost:3001/api/screenshot/proxy', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          url: url,
          viewport: '1440x900',
          format: 'PNG'
        })
      });

      if (!response.ok) {
        throw new Error('Failed to capture screenshot');
      }

      // Convert response to blob and create object URL
      const blob = await response.blob();
      const imageUrl = URL.createObjectURL(blob);

      // Load the image
      const img = await loadImage(imageUrl);
      const scale = Math.max(state.width / img.naturalWidth, state.height / img.naturalHeight);
      setState(prev => ({
        ...prev,
        img,
        scale,
        offsetX: 0,
        offsetY: 0
      }));
    } catch (e) {
      alert('Failed to load screenshot. Make sure the backend is running.');
      console.error(e);
    }
  };

  const exportCanvasBlob = () => {
    const factor = state.retina ? 2 : 1;
    const w = Math.round(state.width * factor);
    const h = Math.round(state.height * factor);
    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d');

    // Background
    ctx.fillStyle = state.bg;
    ctx.fillRect(0, 0, w, h);

    // Draw image
    if (state.img && state.img.complete) {
      const imgW = state.img.naturalWidth;
      const imgH = state.img.naturalHeight;
      const s = state.scale * (w / state.width);
      const drawW = imgW * s;
      const drawH = imgH * s;
      const x = (w - drawW) / 2 + state.offsetX * (w / state.width);
      const y = (h - drawH) / 2 + state.offsetY * (h / state.height);
      ctx.imageSmoothingQuality = 'high';
      ctx.drawImage(state.img, x, y, drawW, drawH);
    }

    const type = state.format === 'webp' ? 'image/webp' : 'image/png';
    const quality = state.format === 'webp' ? state.quality : 1.0;
    return new Promise(resolve => canvas.toBlob(resolve, type, quality));
  };

  return (
    <div className={`antialiased font-[Inter] min-h-screen transition-colors duration-300 ${
      theme === 'dark'
        ? 'bg-[#0B0F1A] text-slate-100 selection:bg-indigo-500/30 selection:text-indigo-200'
        : 'bg-slate-100 text-slate-900 selection:bg-indigo-200 selection:text-indigo-900'
    }`}>
      {/* Backdrop */}
      <div className="pointer-events-none fixed inset-0" aria-hidden="true">
        {theme === 'dark' ? (
          <>
            <div className="absolute inset-0 bg-[radial-gradient(1200px_600px_at_50%_-20%,rgba(99,102,241,0.08),transparent_50%)]"></div>
            <div className="absolute inset-0 bg-[radial-gradient(900px_500px_at_10%_20%,rgba(56,189,248,0.06),transparent_55%)]"></div>
            <div className="absolute inset-0 bg-[radial-gradient(800px_480px_at_90%_10%,rgba(168,85,247,0.05),transparent_60%)]"></div>
          </>
        ) : (
          <>
            <div className="absolute inset-0 bg-[radial-gradient(1200px_600px_at_50%_-20%,rgba(99,102,241,0.06),transparent_50%)]"></div>
            <div className="absolute inset-0 bg-[radial-gradient(900px_500px_at_10%_20%,rgba(56,189,248,0.04),transparent_55%)]"></div>
            <div className="absolute inset-0 bg-[radial-gradient(800px_480px_at_90%_10%,rgba(168,85,247,0.03),transparent_60%)]"></div>
          </>
        )}
      </div>

      <div className="relative z-10">
        <div className="w-full bg-[#FFF9C4] text-slate-900 text-center text-xs sm:text-sm font-medium py-3 px-4 shadow-sm">
          <a 
            href="https://screenshotlayer.com/" 
            target="_blank" 
            rel="noopener noreferrer"
            className="underline decoration-slate-500/50 hover:decoration-slate-900 transition-colors"
          >
            This app is built using the Screenshotlayer API.
          </a>
        </div>

        <Header theme={theme} onToggleTheme={toggleTheme} />

        <main className="relative z-10">
          <Hero urlInput={urlInput} setUrlInput={setUrlInput} onCapture={handleCapture} theme={theme} />

          <section className="mx-auto max-w-7xl px-6 mt-10 sm:mt-12 pb-20">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              <CanvasEditor state={state} setState={setState} onExport={exportCanvasBlob} theme={theme} />
              <ControlsPanel state={state} setState={setState} theme={theme} />
            </div>
          </section>
        </main>
      </div>
    </div>
  );
}

export default App;

import express from 'express';
import axios from 'axios';
import { 
  buildScreenshotUrl, 
  validateScreenshotParams 
} from '../utils/screenshotHelper.js';

const router = express.Router();

/**
 * POST /api/screenshot
 * Generate a screenshot URL and optionally proxy the image
 * 
 * Body parameters:
 * - url: Target website URL (required)
 * - fullpage: Capture full height (optional, 0 or 1)
 * - width: Thumbnail width in pixels (optional)
 * - viewport: Viewport dimensions (optional, format: widthxheight)
 * - format: Output format (optional, PNG/JPG/GIF/WEBP)
 * - quality: Image quality for lossy formats (optional, 1-100)
 * - scale: Device pixel ratio for Retina (optional, 1-2)
 * - delay: Delay before capture in seconds (optional, 0-20)
 * - force: Force fresh screenshot (optional, 0 or 1)
 * - user_agent: Custom User-Agent header (optional)
 * - accept_lang: Custom Accept-Language header (optional)
 */
router.post('/screenshot', async (req, res, next) => {
  try {
    const params = req.body;

    // Debug logging
    console.log('Request body:', JSON.stringify(req.body, null, 2));
    console.log('Content-Type:', req.get('Content-Type'));

    // Validate parameters
    const validation = validateScreenshotParams(params);
    if (!validation.isValid) {
      return res.status(400).json({
        success: false,
        error: {
          message: 'Invalid parameters',
          type: 'validation_error',
          details: validation.errors
        }
      });
    }

    // Build the secure Screenshotlayer API URL
    const screenshotUrl = buildScreenshotUrl(params);

    // Return the URL for client-side usage (e.g., in <img> tags)
    res.json({
      success: true,
      data: {
        url: screenshotUrl,
        params: {
          target: params.url,
          format: params.format || 'PNG',
          viewport: params.viewport || '1440x900'
        }
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * POST /api/screenshot/proxy
 * Proxy the screenshot request through the server
 * Returns the actual image data
 * 
 * This endpoint is useful when you want to:
 * - Process the image on the server before sending to client
 * - Hide the Screenshotlayer API completely from client
 * - Add additional server-side image manipulation
 */
router.post('/screenshot/proxy', async (req, res, next) => {
  try {
    const params = req.body;

    // Validate parameters
    const validation = validateScreenshotParams(params);
    if (!validation.isValid) {
      return res.status(400).json({
        success: false,
        error: {
          message: 'Invalid parameters',
          type: 'validation_error',
          details: validation.errors
        }
      });
    }

    // Build the secure Screenshotlayer API URL
    const screenshotUrl = buildScreenshotUrl(params);

    // Fetch the image from Screenshotlayer
    const response = await axios.get(screenshotUrl, {
      responseType: 'arraybuffer',
      timeout: 30000 // 30 second timeout
    });

    // Determine content type based on format
    const format = (params.format || 'PNG').toLowerCase();
    const contentTypeMap = {
      'png': 'image/png',
      'jpg': 'image/jpeg',
      'jpeg': 'image/jpeg',
      'gif': 'image/gif',
      'webp': 'image/webp'
    };

    const contentType = contentTypeMap[format] || 'image/png';

    // Send the image back to client
    res.set('Content-Type', contentType);
    res.set('Cache-Control', 'public, max-age=86400'); // Cache for 24 hours
    res.send(response.data);
  } catch (error) {
    next(error);
  }
});

/**
 * GET /api/screenshot/url
 * Generate a screenshot URL via query parameters
 * Useful for simple GET requests
 */
router.get('/screenshot/url', (req, res, next) => {
  try {
    const params = req.query;

    // Validate parameters
    const validation = validateScreenshotParams(params);
    if (!validation.isValid) {
      return res.status(400).json({
        success: false,
        error: {
          message: 'Invalid parameters',
          type: 'validation_error',
          details: validation.errors
        }
      });
    }

    // Build the secure Screenshotlayer API URL
    const screenshotUrl = buildScreenshotUrl(params);

    res.json({
      success: true,
      data: {
        url: screenshotUrl
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * GET /api/health
 * Health check endpoint
 */
router.get('/health', (req, res) => {
  res.json({
    success: true,
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

export default router;

import dotenv from 'dotenv';

dotenv.config();

export const config = {
  screenshotlayer: {
    accessKey: process.env.SCREENSHOTLAYER_ACCESS_KEY,
    secretKeyword: process.env.SCREENSHOTLAYER_SECRET_KEYWORD,
    baseUrl: 'https://api.screenshotlayer.com/api/capture'
  },
  server: {
    port: process.env.PORT || 3001,
    nodeEnv: process.env.NODE_ENV || 'development'
  },
  cors: {
    allowedOrigins: process.env.ALLOWED_ORIGINS 
      ? process.env.ALLOWED_ORIGINS.split(',')
      : ['http://localhost:3000', 'http://localhost:5173']
  }
};

// Validate required environment variables
export const validateConfig = () => {
  const required = [
    'SCREENSHOTLAYER_ACCESS_KEY',
    'SCREENSHOTLAYER_SECRET_KEYWORD'
  ];

  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}\n` +
      'Please copy .env.example to .env and fill in your values.'
    );
  }
};

/**
 * Global error handler middleware
 */
export const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Handle axios errors from Screenshotlayer API
  if (err.response) {
    const status = err.response.status || 500;
    let message = err.message;
    let type = 'api_error';
    let code = status;

    try {
      // Attempt to parse JSON even if responseType was arraybuffer
      const contentType = err.response.headers?.['content-type'] || '';
      if (contentType.includes('application/json')) {
        const data = typeof err.response.data === 'string'
          ? JSON.parse(err.response.data)
          : (err.response.data instanceof ArrayBuffer
              ? JSON.parse(Buffer.from(err.response.data).toString('utf8'))
              : err.response.data);
        if (data && data.error) {
          message = data.error.info || message;
          type = data.error.type || type;
          code = data.error.code || code;
        }
      } else if (err.response.data instanceof ArrayBuffer) {
        // Fallback: try to read text
        const text = Buffer.from(err.response.data).toString('utf8');
        message = text || message;
      }
    } catch (parseErr) {
      // ignore parse errors
    }

    return res.status(status).json({
      success: false,
      error: { message, type, code }
    });
  }

  // Handle validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      success: false,
      error: {
        message: err.message,
        type: 'validation_error',
        details: err.errors
      }
    });
  }

  // Handle generic errors
  res.status(err.status || 500).json({
    success: false,
    error: {
      message: err.message || 'Internal server error',
      type: err.type || 'internal_error'
    }
  });
};

/**
 * Not found handler middleware
 */
export const notFoundHandler = (req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: 'Route not found',
      type: '404_not_found',
      path: req.originalUrl
    }
  });
};

import crypto from 'crypto';
import { config } from '../config/config.js';

/**
 * Generate MD5 hash for URL encryption
 * @param {string} url - Target website URL
 * @param {string} secretKeyword - Secret keyword from config
 * @returns {string} MD5 hash
 */
export const generateSecretKey = (url, secretKeyword) => {
  const combined = url + secretKeyword;
  return crypto.createHash('md5').update(combined).digest('hex');
};

/**
 * Build Screenshotlayer API URL with all parameters
 * @param {object} params - Screenshot parameters
 * @returns {string} Complete API URL
 */
export const buildScreenshotUrl = (params) => {
  const { url, ...options } = params;

  if (!url) {
    throw new Error('URL parameter is required');
  }

  // IMPORTANT: Do NOT pre-encode the URL here.
  // URLSearchParams will properly encode it; pre-encoding would double-encode and break the API.

  // Generate secret key
  const secretKey = generateSecretKey(
    url, 
    config.screenshotlayer.secretKeyword
  );

  // Build query parameters
  const queryParams = new URLSearchParams({
    access_key: config.screenshotlayer.accessKey,
    secret_key: secretKey,
    url // let URLSearchParams handle encoding
  });

  // Add optional parameters
  const optionalParams = [
    'fullpage', 'width', 'viewport', 'format', 'quality',
    'css_url', 'delay', 'ttl', 'force', 'placeholder',
    'user_agent', 'accept_lang', 'scale'
  ];

  optionalParams.forEach(param => {
    if (options[param] !== undefined && options[param] !== null && options[param] !== '') {
      let value = options[param];
      // Normalize booleans for APIs expecting 0/1
      if ((param === 'fullpage' || param === 'force' || param === 'placeholder') && typeof value === 'boolean') {
        value = value ? '1' : '0';
      }
      queryParams.append(param, value);
    }
  });

  return `${config.screenshotlayer.baseUrl}?${queryParams.toString()}`;
};

/**
 * Validate screenshot parameters
 * @param {object} params - Parameters to validate
 * @returns {object} Validation result
 */
export const validateScreenshotParams = (params) => {
  const errors = [];

  // Validate required URL
  if (!params.url) {
    errors.push('url is required');
  } else {
    // Basic URL validation
    try {
      new URL(params.url);
    } catch (e) {
      errors.push('url must be a valid URL (include http:// or https://)');
    }
  }

  // Validate optional parameters
  if (params.width && (isNaN(params.width) || params.width < 1)) {
    errors.push('width must be a positive number');
  }

  if (params.viewport && !/^\d+x\d+$/.test(params.viewport)) {
    errors.push('viewport must be in format: widthxheight (e.g., 1440x900)');
  }

  if (params.format && !['PNG', 'JPG', 'JPEG', 'GIF', 'WEBP'].includes(params.format.toUpperCase())) {
    errors.push('format must be one of: PNG, JPG, JPEG, GIF, WEBP');
  }

  if (params.quality && (isNaN(params.quality) || params.quality < 1 || params.quality > 100)) {
    errors.push('quality must be between 1 and 100');
  }

  if (params.delay && (isNaN(params.delay) || params.delay < 0 || params.delay > 20)) {
    errors.push('delay must be between 0 and 20 seconds');
  }

  if (params.scale && (isNaN(params.scale) || params.scale < 1 || params.scale > 2)) {
    errors.push('scale must be between 1 and 2');
  }

  if (params.fullpage && !['0', '1', 0, 1, true, false].includes(params.fullpage)) {
    errors.push('fullpage must be 0, 1, true, or false');
  }

  if (params.force && !['0', '1', 0, 1, true, false].includes(params.force)) {
    errors.push('force must be 0, 1, true, or false');
  }

  return {
    isValid: errors.length === 0,
    errors
  };
};

